interface User { id: number; name: string; }

function App() {
  const [user, setUser] = useState<User | null>(null);
  const load = () => setUser({ id: 1, name: 'Ada' });
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <button onClick={load}>Load</button>
      <p>{user ? user.name : 'No user'}</p>
    </div>
  );
}

function useLocalStorage<T>(key: string, initial: T): [T, (value: T) => void] {
  const [value, setValue] = useState<T>(() => {
    const raw = localStorage.getItem(key);
    return raw ? (JSON.parse(raw) as T) : initial;
  });
  const update = (next: T) => {
    setValue(next);
    localStorage.setItem(key, JSON.stringify(next));
  };
  return [value, update];
}

function App() {
  const [name, setName] = useLocalStorage<string>('name', '');
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <input value={name} onChange={(e: React.ChangeEvent<HTMLInputElement>) => setName(e.target.value)} placeholder="Your name" />
      <p>Saved: {name || '(empty)'}</p>
    </div>
  );
}
